import{z as l,x as p,o as t,c as A,q as o,j as E,D as n,d as r,s,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"Friedman 货币数量重述","description":"","frontmatter":{"title":"Friedman 货币数量重述","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/friedman-quantity.md","filePath":"econ/friedman-quantity.md","lastUpdated":1791063341000}'),m={name:"econ/friedman-quantity.md"};function B(f,a,h,u,y,c){const i=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=o('<h1 id="friedman-货币数量重述" tabindex="-1">Friedman 货币数量重述 <a class="header-anchor" href="#friedman-货币数量重述" aria-label="Permalink to &quot;Friedman 货币数量重述&quot;">​</a></h1><div class="epigraph"><p>数量理论首先是货币需求理论；流通速度不是常数，而是少数变量的稳定函数。</p><footer>—— Friedman, The Quantity Theory of Money: A Restatement, in Studies in the Quantity Theory of Money, 1956</footer></div><p><a href="/econ/keynes-general-theory">上一课</a>（Keynes《通论》问题设定）。附录对照。主干<a href="/econ/quantity-theory">数量方程与货币中性</a>已用 \\(MV=PY\\) 当会计，并讨论长期中性。本篇对照 <strong>1956 年原文</strong>：把数量理论从机械的速度常数，重写成资产组合里的货币需求，以对抗当时把数量论当成过时身份的说法。不重讲<a href="/econ/keynes-general-theory">凯恩斯</a>的有效需求章。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>费雪交易方程把 \\(V\\) 写成制度常数，凯恩斯传统把货币需求写成利率极敏感、危机时可以无底（流动性陷阱）。Friedman 的缺口是第三条路：货币是众多资产之一，需求取决于财富、相对回报、以及把债券、股权、实物、人力资本换成货币的激励。若这组自变量稳定，则 \\(V\\) 可预测，数量理论作为<strong>经验的货币需求</strong>复活，而不需要 \\(V\\) 字面不变。</p><p>1956 文是芝加哥讨论班的纲领，不是一篇回归。经验工作在 Friedman 与 Schwartz 的货币史里另做。附录对照的是问题重述本身。</p><p><span class="marginnote">货币需求写成 \\(M=P\\cdot f(y,w,r_b,r_e,\\dot p/p,\\ldots)\\)：实际余额对实际收入/财富与各资产回报。这与剑桥 \\(k\\) 是亲戚，但 \\(k\\) 不再是制度常数。1968 年 AER 演说把自然率接进来，是后一篇，不是 1956 的本文。</span></p><p><span class="marginnote">流通速度 \\(V\\) 翻译过来就是「每一块钱一年被转手几次」：名义 GDP 除以货币量。若货币 20 万亿、GDP 100 万亿，\\(V=5\\)——每块钱一年平均经手 5 次。Friedman 的要点：这个 5 不是常数，但由少数稳定因素决定，因此可以预测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把持有货币的机会成本展开：债券利率、股权预期回报、实物的预期升值（通胀）、人力资本与非人力财富之比。价格水平进入是因为需求是实际余额。稳定的 \\(f(\\cdot)\\) 意味着：名义货币的外生变动，长期主要打在 \\(P\\) 上，短期可以打在 \\(y\\) 上——这为后来的短期非中性、长期中性提供了需求侧语言，而不接受流动性陷阱作为常态。</p>',10)),(t(),E(d,null,{default:n(()=>[s(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%B4%A2%E5%AF%8C%E4%B8%8E%E6%94%B6%E5%85%A5%22%5D%20--%3E%20MD%5B%22%E8%B4%A7%E5%B8%81%E9%9C%80%E6%B1%82%20f%22%5D%0A%20%20R%5B%22%E5%80%BA%E5%88%B8%E3%80%81%E8%82%A1%E6%9D%83%E3%80%81%E9%80%9A%E8%83%80%E7%AD%89%E5%9B%9E%E6%8A%A5%22%5D%20--%3E%20MD%0A%20%20MD%20--%3E%20V%5B%22%E9%80%9F%E5%BA%A6%20V%20%E6%98%AF%20f%20%E7%9A%84%E5%80%92%E6%95%B0%22%5D%0A%20%20V%20--%3E%20QTM%5B%22MV%3DPY%20%E4%BD%9C%E4%B8%BA%E4%BC%9A%E8%AE%A1%2C%20%E4%B8%8D%E6%98%AF%E5%B8%B8%E6%95%B0%20V%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与《通论》的对照焦点是投机动机。Keynes 让债券利率几乎单独决定货币需求的波动；Friedman 把利率只当作 \\(f\\) 的一个自变量，并主张其弹性不足以让政策在流动性里消失。这是经验主张，1956 年并未完成检验。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"把货币想进资产组合，就像家里的现金抽屉：留多少现金，取决于「取用方便」与「放着亏利息」之间的权衡。存款利率高、股票行情好时抽屉就空一点——货币只是众多资产里流动性最好的那一个，不是唯一的储值方式。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是资产替代，不是交易技术。货币提供非货币服务（便利、安全），其边际服务在存量上升时递减，于是有一条向下的实际余额需求。外生的 \\(M\\) 增加，若 \\(f\\) 暂时不动，只能 \\(P\\) 或 \\(y\\) 动；待相对回报与预期调完，\\(y\\) 回到由实物因素决定的路径，\\(P\\) 按比例动。主干数量课的中性，在这里是需求函数稳定时的长期推论，不是恒等式。",-1)),(t(),E(d,null,{default:n(()=>[s(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20MUP%5B%22%E5%A4%96%E7%94%9F%20M%20%E5%A2%9E%E5%8A%A0%22%5D%20--%3E%20SHORT%5B%22%E7%9F%AD%E6%9C%9F%3A%20f%20%E6%9A%82%E6%97%B6%E6%9C%AA%E5%8A%A8%22%5D%0A%20%20SHORT%20--%3E%20YUP%5B%22%E4%BA%A7%E5%87%BA%20y%20%E6%9A%82%E6%97%B6%E4%B8%8A%E5%8D%87%22%5D%0A%20%20MUP%20--%3E%20ADJ%5B%22%E7%9B%B8%E5%AF%B9%E5%9B%9E%E6%8A%A5%E4%B8%8E%E9%A2%84%E6%9C%9F%E9%80%90%E6%B8%90%E8%B0%83%E6%95%B4%22%5D%0A%20%20ADJ%20--%3E%20LONG%5B%22%E9%95%BF%E6%9C%9F%3A%20y%20%E5%9B%9E%E5%88%B0%E5%AE%9E%E7%89%A9%E8%B7%AF%E5%BE%84%22%5D%0A%20%20LONG%20--%3E%20PUP%5B%22%E4%BB%B7%E6%A0%BC%20P%20%E6%8C%89%E6%AF%94%E4%BE%8B%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">常见误区：以为 Friedman 主张 \\(V\\) 字面不变。他的原话是 \\(V\\) 是「少数变量的稳定函数」——通胀升、持币更贵，\\(V\\) 会动，但动得可预测。真正打脸的是 1980 年代后金融创新让需求函数本身漂移，\\(V\\) 连方向都难猜。</span></p><h3 id="对照主干数量课-不重开" tabindex="-1">对照主干数量课，不重开 \\(MV=PY\\) <a class="header-anchor" href="#对照主干数量课-不重开" aria-label="Permalink to &quot;对照主干数量课，不重开 $MV=PY$&quot;">​</a></h3><p>主干<a href="/econ/quantity-theory">数量方程</a>已钉会计与中性。1956 年重述把稳定性放在需求一侧：\\(M^d=P\\cdot f(y_p,r,\\pi^e,\\ldots)\\)。Keynes 的投机需求把 \\(f\\) 写得不稳定，于是 \\(M\\) 可被 \\(V\\) 抵消。Friedman 的条件句是：若 \\(f\\) 稳定，名义收入随货币。1968 年 AER 把同一逻辑推到自然率，附录以 1956 为主。不要把 2014 年内生货币操作读进该文，也不要把泰勒规则写成 1956 年的脚注。</p><p><span class="marginnote">Friedman, &quot;The Quantity Theory of Money: A Restatement,&quot; in <em>Studies in the Quantity Theory of Money</em>, University of Chicago Press, 1956。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1956 说成已经证明规则优于权变——那是 <a href="/econ/kydland-prescott">Kydland–Prescott 1977</a>。也不要把恒定货币增长率规则安在这篇名下：规则是后来政策文的主张。经验上 1970–80 年代货币需求「失踪」，正是对「\\(f\\) 稳定」的打击；附录对照问题设定，不在这里重做 M1 回归。</p><p>铸币税与通胀税是主干<a href="/econ/seigniorage">铸币税</a>的缺口，1956 文只间接涉及机会成本里的 \\(\\dot p\\)。下一篇附录把政策从需求函数换成时间一致：最优计划可以事后不想执行。</p><p>需求函数是条件句：若 \\(f\\) 稳定，数量理论作为因果才有牙齿。金融创新使 \\(f\\) 移动时，应改写需求，而不是改写恒等式。</p><p>永久收入进入 \\(f\\)，与 Friedman 的消费理论同源：暂时收入不按一比一增加货币持有。</p><p>操作上把 \\(M\\) 当工具，是后来货币主义的政策文；1956 年重述本身停在需求。</p><p>内生货币主干已经说明盯利率时 \\(M\\) 不是外生。两套课不要合成一句「Friedman 错了所以贷款创造存款」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Friedman 1956：数量论是稳定的货币需求，不是恒定 \\(V\\)。</li><li>货币进入资产组合；长期中性是 \\(f\\) 稳定时的推论。</li><li>对抗的是机械数量论与流动性陷阱常态，不是 IS–LM 的画法本身。</li><li>出处：Friedman, in <em>Studies in the Quantity Theory of Money</em>, 1956。</li></ul>',13))])}const F=l(m,[["render",B]]);export{P as __pageData,F as default};
